type HudPosition = "top-left" | "top-right" | "bottom-left" | "bottom-right" | "top-center" | "bottom-center";

// The overlay window is now the whole app (chat, settings, knowledge base) -
// there used to be a separate 1300x1000 control-panel window, removed in
// favor of a single content-protected window. hudWindow stays separate: a
// deliberately tiny, non-interactive status readout.
let overlayWindow: BrowserWindow | null = null;
let hudWindow: BrowserWindow | null = null;
let tray: Tray | null = null;
let overlayClickThrough = false;
let currentMode: InterviewMode = "coding";
let isQuitting = false;

const HUD_WIDTH = 260;
const HUD_HEIGHT = 36;
const HUD_MARGIN = 16;

// Sends an IPC event to every live window (app window, HUD) so both stay in
// sync even though they're separate renderer processes.
function broadcast(channel: string, payload?: any): void {
  for (const win of [overlayWindow, hudWindow]) {
    if (win && !win.isDestroyed()) {
      win.webContents.send(channel, payload);
    }
  }
}

function computeHudBounds(position: HudPosition): { x: number; y: number } {
  const { x: areaX, y: areaY, width, height } = screen.getPrimaryDisplay().workArea;
  switch (position) {
    case "top-left":
      return { x: areaX + HUD_MARGIN, y: areaY + HUD_MARGIN };
    case "top-right":
      return { x: areaX + width - HUD_WIDTH - HUD_MARGIN, y: areaY + HUD_MARGIN };
    case "bottom-left":
      return { x: areaX + HUD_MARGIN, y: areaY + height - HUD_HEIGHT - HUD_MARGIN };
    case "bottom-right":
      return { x: areaX + width - HUD_WIDTH - HUD_MARGIN, y: areaY + height - HUD_HEIGHT - HUD_MARGIN };
    case "bottom-center":
      return { x: areaX + Math.round((width - HUD_WIDTH) / 2), y: areaY + height - HUD_HEIGHT - HUD_MARGIN };
    case "top-center":
    default:
      return { x: areaX + Math.round((width - HUD_WIDTH) / 2), y: areaY + HUD_MARGIN };
  }
}

// The whole app: chat, settings, knowledge base. Content-protected (invisible
// to screen capture) regardless of size, so there's no stealth reason to keep
// it small - it lives in the tray instead of the taskbar/Alt-Tab list, and
// closing it (Alt-F4 - there's no frame/close button) hides it rather than
// quitting; only the tray's own Quit item exits.
const createOverlayWindow = (): void => {
  if (overlayWindow && !overlayWindow.isDestroyed()) {
    return;
  }

  const savedConfig = store.get("config") || {};
  const savedBounds = savedConfig.overlay_bounds;
  overlayClickThrough = !!savedConfig.overlay_click_through_always_on;

  overlayWindow = new BrowserWindow({
    width: savedBounds?.width || 520,
    height: savedBounds?.height || 780,
    minWidth: 400,
    minHeight: 520,
    x: savedBounds?.x,
    y: savedBounds?.y,
    frame: false,
    transparent: true,
    resizable: true,
    skipTaskbar: true,
    hasShadow: true,
    show: false,
    webPreferences: {
      preload: MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY,
      contextIsolation: true,
      nodeIntegration: false,
      webSecurity: false,
    },
  });

  overlayWindow.webContents.session.webRequest.onHeadersReceived((details, callback) => {
    callback({
      responseHeaders: {
        ...details.responseHeaders,
        "Content-Security-Policy": [
          "default-src 'self' 'unsafe-inline' 'unsafe-eval' data: blob:; script-src 'self' 'unsafe-inline' 'unsafe-eval' blob:; connect-src 'self' https://api.openai.com;",
        ],
      },
    });
  });

  overlayWindow.webContents.session.setPermissionRequestHandler((webContents, permission, callback) => {
    callback(permission === "media");
  });

  overlayWindow.setAlwaysOnTop(true, "screen-saver");
  overlayWindow.setContentProtection(true);
  overlayWindow.setVisibleOnAllWorkspaces(true, { visibleOnFullScreen: true });
  overlayWindow.setIgnoreMouseEvents(overlayClickThrough, { forward: true });
  overlayWindow.setOpacity(typeof savedConfig.window_opacity === "number" ? savedConfig.window_opacity : 1);

  overlayWindow.loadURL(MAIN_WINDOW_WEBPACK_ENTRY + "#/overlay");
  overlayWindow.once("ready-to-show", () => {
    // Only the very first open should grab focus - the hotkey/tray toggle
    // re-shows via showInactive() so it doesn't steal focus from whatever
    // the user was doing.
    overlayWindow?.show();
  });

  overlayWindow.on("close", (event) => {
    if (!isQuitting) {
      event.preventDefault();
      overlayWindow?.hide();
      broadcast("overlay-visibility-changed", { visible: false });
    }
  });

  const persistBounds = () => {
    if (!overlayWindow) return;
    const config = store.get("config") || {};
    store.set("config", { ...config, overlay_bounds: overlayWindow.getBounds() });
  };
  overlayWindow.on("moved", persistBounds);
  overlayWindow.on("resized", persistBounds);

  overlayWindow.on("closed", () => {
    overlayWindow = null;
  });
};

// Shared by the hotkey, the IPC handler, and the tray menu - avoids three
// copies of the same show/hide/create logic drifting apart.
function toggleOverlayWindow(): boolean {
  if (!overlayWindow || overlayWindow.isDestroyed()) {
    createOverlayWindow();
    broadcast("overlay-visibility-changed", { visible: true });
    return true;
  }
  if (overlayWindow.isVisible()) {
    overlayWindow.hide();
    broadcast("overlay-visibility-changed", { visible: false });
    return false;
  }
  overlayWindow.showInactive();
  broadcast("overlay-visibility-changed", { visible: true });
  return true;
}

// Read-only status readout - shows whether the overlay is visible and
// whether click-through ("cursor protection") is on, so that information
// isn't lost when the overlay itself is hidden. Never receives input and is
// itself excluded from screen capture, same as the overlay.
const createHudWindow = (): void => {
  if (hudWindow && !hudWindow.isDestroyed()) {
    return;
  }

  const savedConfig = store.get("config") || {};
  const position: HudPosition = savedConfig.hud_position || "top-right";
  const { x, y } = computeHudBounds(position);

  hudWindow = new BrowserWindow({
    width: HUD_WIDTH,
    height: HUD_HEIGHT,
    x,
    y,
    frame: false,
    transparent: true,
    resizable: false,
    skipTaskbar: true,
    hasShadow: false,
    focusable: false,
    show: false,
    webPreferences: {
      preload: MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY,
      contextIsolation: true,
      nodeIntegration: false,
      webSecurity: false,
    },
  });

  hudWindow.setAlwaysOnTop(true, "screen-saver");
  hudWindow.setContentProtection(true);
  hudWindow.setVisibleOnAllWorkspaces(true, { visibleOnFullScreen: true });
  hudWindow.setIgnoreMouseEvents(true);

  hudWindow.loadURL(MAIN_WINDOW_WEBPACK_ENTRY + "#/hud");
  hudWindow.once("ready-to-show", () => {
    hudWindow?.showInactive();
  });

  hudWindow.on("closed", () => {
    hudWindow = null;
  });
};

function repositionHud(position: HudPosition): void {
  if (!hudWindow || hudWindow.isDestroyed()) return;
  const { x, y } = computeHudBounds(position);
  hudWindow.setPosition(x, y);
}

function createTray(): void {
  if (tray) return;

  const icon = nativeImage.createFromPath(trayIconPath);
  tray = new Tray(icon.isEmpty() ? icon : icon.resize({ width: 16, height: 16 }));
  tray.setToolTip("Interview Assistant");
  tray.on("click", () => toggleOverlayWindow());
  updateTrayMenu();
}

function updateTrayMenu(): void {
  if (!tray) return;
  const visible = !!overlayWindow && !overlayWindow.isDestroyed() && overlayWindow.isVisible();
  const menu = Menu.buildFromTemplate([
    { label: visible ? "Hide Window" : "Show Window", click: () => toggleOverlayWindow() },
    { type: "separator" },
    {
      // Fail-safe: if click-through gets stuck on, the window itself is
      // unclickable, so this needs to be reachable from outside it.
      label: "Click-through (mouse passes through window)",
      type: "checkbox",
      checked: overlayClickThrough,
      click: () => {
        overlayClickThrough = !overlayClickThrough;
        overlayWindow?.setIgnoreMouseEvents(overlayClickThrough, { forward: true });
        broadcast("hotkey", { action: "click-through-changed", value: overlayClickThrough });
        updateTrayMenu();
      },
    },
    { type: "separator" },
    {
      label: "Quit",
      click: () => {
        isQuitting = true;
        app.quit();
      },
    },
  ]);
  tray.setContextMenu(menu);
}

interface HotkeyDef {
  id: string;
  label: string;
  accelerator: string;
  handler: () => void;
}

// Registration status per hotkey, so failures (usually a conflict with
// another app already holding that combo) are visible instead of silent -
// globalShortcut.register() returns false on conflict, it does not throw.
const hotkeyStatus = new Map<string, { accelerator: string; registered: boolean }>();

// Triple-modifier combos to cut down on collisions with other apps' global
// hotkeys (Ctrl+Shift+H/Enter/X in particular are commonly already taken).
// Overridable per-id via config.hotkey_overrides, see getHotkeyDefs().
const DEFAULT_ACCELERATORS: Record<string, string> = {
  "toggle-overlay": "CommandOrControl+Alt+Shift+O",
  "ask-now": "CommandOrControl+Alt+Shift+Enter",
  "cycle-mode": "CommandOrControl+Shift+M",
  "clear-transcript": "CommandOrControl+Alt+Shift+X",
  "click-through": "CommandOrControl+Shift+L",
  "region-select": "CommandOrControl+Alt+Shift+S",
  "toggle-auto-answer": "CommandOrControl+Alt+Shift+A",
  "regenerate-last": "CommandOrControl+Alt+Shift+R",
  "model-slot-1": "CommandOrControl+Alt+1",
  "model-slot-2": "CommandOrControl+Alt+2",
  "model-slot-3": "CommandOrControl+Alt+3",
  "model-slot-4": "CommandOrControl+Alt+4",
  "model-slot-5": "CommandOrControl+Alt+5",
};

const MODEL_SLOT_COUNT = 5;

function getHotkeyDefs(config: any = {}): HotkeyDef[] {
  const overrides: Record<string, string> = config.hotkey_overrides || {};
  const accel = (id: string) => overrides[id] || DEFAULT_ACCELERATORS[id];

  return [
    {
      id: "toggle-overlay",
      label: "Show/hide overlay",
      accelerator: accel("toggle-overlay"),
      handler: () => toggleOverlayWindow(),
    },
    {
      id: "ask-now",
      label: "Ask now",
      accelerator: accel("ask-now"),
      handler: () => broadcast("hotkey", { action: "ask-now" }),
    },
    {
      id: "cycle-mode",
      label: "Cycle mode",
      accelerator: accel("cycle-mode"),
      handler: () => {
        currentMode = nextMode(currentMode);
        broadcast("mode-changed", { mode: currentMode });
      },
    },
    {
      id: "clear-transcript",
      label: "Clear transcript",
      accelerator: accel("clear-transcript"),
      handler: () => broadcast("hotkey", { action: "clear-transcript" }),
    },
    {
      id: "click-through",
      label: "Toggle click-through",
      accelerator: accel("click-through"),
      handler: () => {
        if (!overlayWindow || overlayWindow.isDestroyed()) return;
        overlayClickThrough = !overlayClickThrough;
        overlayWindow.setIgnoreMouseEvents(overlayClickThrough, { forward: true });
        broadcast("hotkey", { action: "click-through-changed", value: overlayClickThrough });
        updateTrayMenu();
      },
    },
    {
      id: "region-select",
      label: "Screenshot (region select)",
      accelerator: accel("region-select"),
      handler: () => broadcast("hotkey", { action: "region-select" }),
    },
    {
      id: "toggle-auto-answer",
      label: "Toggle auto-answer",
      accelerator: accel("toggle-auto-answer"),
      handler: () => broadcast("hotkey", { action: "toggle-auto-answer" }),
    },
    {
      id: "regenerate-last",
      label: "Regenerate last answer",
      accelerator: accel("regenerate-last"),
      handler: () => broadcast("hotkey", { action: "regenerate-last" }),
    },
    ...Array.from({ length: MODEL_SLOT_COUNT }, (_, i) => {
      const slot = i + 1;
      const id = `model-slot-${slot}`;
      return {
        id,
        label: `Switch to model slot ${slot}`,
        accelerator: accel(id),
        handler: () => broadcast("hotkey", { action: "switch-model-slot", slot }),
      };
    }),
  ];
}

function registerGlobalShortcuts(): void {
  globalShortcut.unregisterAll();
  hotkeyStatus.clear();

  const config = store.get("config") || {};
  for (const def of getHotkeyDefs(config)) {
    const registered = globalShortcut.register(def.accelerator, def.handler);
    hotkeyStatus.set(def.id, { accelerator: def.accelerator, registered });
    if (!registered) {
      console.warn(
        `[hotkeys] Failed to register "${def.accelerator}" (${def.label}) - it's probably already bound by another app.`
      );
    }
  }
}

