// Region-select screenshot: a full-screen, click-enabled, content-protected
// overlay the user drags a rectangle on, closed the instant the drag ends -
// so it never lingers in front of whatever's being screen-shared.
let selectionWindow: BrowserWindow | null = null;

function createSelectionWindow(): void {
  if (selectionWindow && !selectionWindow.isDestroyed()) return;
  const display = screen.getPrimaryDisplay();

  selectionWindow = new BrowserWindow({
    x: display.bounds.x,
    y: display.bounds.y,
    width: display.bounds.width,
    height: display.bounds.height,
    frame: false,
    transparent: true,
    // Windows renders a transparent BrowserWindow as solid black until an
    // explicit alpha backgroundColor is set - without it the window showed
    // before the renderer painted, covering the whole screen with black.
    backgroundColor: "#00000000",
    resizable: false,
    movable: false,
    fullscreenable: false,
    skipTaskbar: true,
    hasShadow: false,
    show: false,
    webPreferences: {
      preload: MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY,
      contextIsolation: true,
      nodeIntegration: false,
      webSecurity: false,
    },
  });

  selectionWindow.setAlwaysOnTop(true, "screen-saver");
  selectionWindow.setContentProtection(true);
  selectionWindow.setVisibleOnAllWorkspaces(true, { visibleOnFullScreen: true });
  selectionWindow.loadURL(MAIN_WINDOW_WEBPACK_ENTRY + "#/region-select");
  selectionWindow.once("ready-to-show", () => {
    selectionWindow?.show();
  });

  selectionWindow.on("closed", () => {
    selectionWindow = null;
  });
}

ipcMain.handle("open-region-select", () => {
  createSelectionWindow();
});

ipcMain.handle("cancel-region-select", () => {
  selectionWindow?.close();
});

ipcMain.handle(
  "capture-region",
  async (event, rect: { x: number; y: number; width: number; height: number }) => {
    selectionWindow?.close();
    try {
      const display = screen.getPrimaryDisplay();
      const scaleFactor = display.scaleFactor;
      const captureWidth = Math.round(display.size.width * scaleFactor);
      const captureHeight = Math.round(display.size.height * scaleFactor);

      const sources = await desktopCapturer.getSources({
        types: ["screen"],
        thumbnailSize: { width: captureWidth, height: captureHeight },
      });
      if (!sources[0] || sources[0].thumbnail.isEmpty()) {
        broadcast("region-captured", { dataUrl: null, error: "Could not capture the screen." });
        return;
      }

      const cropped = sources[0].thumbnail.crop({
        x: Math.max(0, Math.round(rect.x * scaleFactor)),
        y: Math.max(0, Math.round(rect.y * scaleFactor)),
        width: Math.max(1, Math.round(rect.width * scaleFactor)),
        height: Math.max(1, Math.round(rect.height * scaleFactor)),
      });
      broadcast("region-captured", { dataUrl: cropped.toDataURL() });
    } catch (err: any) {
      broadcast("region-captured", { dataUrl: null, error: err?.message || "Screenshot failed." });
    }
  }
);

ipcMain.handle("parsePDF", async (event, pdfBuffer) => {
  try {
    const pdf = require("pdf-parse");
    const data = await pdf(Buffer.from(pdfBuffer), {
      max: 0,
    });
    return { text: data.text };
  } catch (error) {
    return { error: "Failed to parse PDF: " + error.message };
  }
});

ipcMain.handle("process-image", async (event, imageData) => {
  try {
    const sharp = require("sharp");
    let image;
    if (imageData.startsWith("data:image")) {
      const base64Data = imageData.split(",")[1];
      const imageBuffer = Buffer.from(base64Data, "base64");
      image = sharp(imageBuffer);
    } else {
      throw new Error(
        "Invalid image input: expected Base64 encoded image data"
      );
    }
    const metadata = await image.metadata();
    return `Image size: ${metadata.width}x${metadata.height}, Format: ${metadata.format}`;
  } catch (error) {
    return { error: "Failed to process image: " + error.message };
  }
});

